     1→import { describe, it, expect, beforeAll, afterAll } from "bun:test";
     2→import { startTestServer, type TestServer } from "../helpers";
     3→import { createAdventure } from "../../src/db/adventures";
     4→import { createImageRecord } from "../../src/db/images";
     5→
     6→describe("Adventure API", () => {
     7→  let ts: TestServer;
     8→
     9→  beforeAll(() => {
    10→    ts = startTestServer();
    11→  });
    12→
    13→  afterAll(() => {
    14→    ts.stop();
    15→  });
    16→
    17→  it("POST /api/adventures with valid body returns 201 + adventure", async () => {
    18→    const res = await fetch(`${ts.url}/api/adventures`, {
    19→      method: "POST",
    20→      headers: { "Content-Type": "application/json" },
    21→      body: JSON.stringify({ name: "Test Adventure", gmPassword: "secret" }),
    22→    });
    23→    expect(res.status).toBe(201);
    24→    const data = await res.json();
    25→    expect(data.id).toBeDefined();
    26→    expect(data.name).toBe("Test Adventure");
    27→    expect(data.player_link).toBeDefined();
    28→  });
    29→
    30→  it("POST /api/adventures with empty name returns 400", async () => {
    31→    const res = await fetch(`${ts.url}/api/adventures`, {
    32→      method: "POST",
    33→      headers: { "Content-Type": "application/json" },
    34→      body: JSON.stringify({ name: "", gmPassword: "secret" }),
    35→    });
    36→    expect(res.status).toBe(400);
    37→    const data = await res.json();
    38→    expect(data.error).toBeDefined();
    39→  });
    40→
    41→  it("POST /api/adventures with missing gmPassword returns 400", async () => {
    42→    const res = await fetch(`${ts.url}/api/adventures`, {
    43→      method: "POST",
    44→      headers: { "Content-Type": "application/json" },
    45→      body: JSON.stringify({ name: "Test" }),
    46→    });
    47→    expect(res.status).toBe(400);
    48→  });
    49→
    50→  it("GET /api/adventures/:id with correct password returns 200", async () => {
    51→    const adventure = createAdventure(ts.db, { name: "Test", gmPassword: "pw" });
    52→    const res = await fetch(`${ts.url}/api/adventures/${adventure.id}`, {
    53→      headers: { "X-GM-Password": "pw" },
    54→    });
    55→    expect(res.status).toBe(200);
    56→    const data = await res.json();
    57→    expect(data.id).toBe(adventure.id);
    58→  });
    59→
    60→  it("GET /api/adventures/:id with wrong password returns 401", async () => {
    61→    const adventure = createAdventure(ts.db, { name: "Test", gmPassword: "pw" });
    62→    const res = await fetch(`${ts.url}/api/adventures/${adventure.id}`, {
    63→      headers: { "X-GM-Password": "wrong" },
    64→    });
    65→    expect(res.status).toBe(401);
    66→  });
    67→
    68→  it("GET /api/adventures/:id with unknown id returns 404", async () => {
    69→    const res = await fetch(`${ts.url}/api/adventures/nonexistent-id`, {
    70→      headers: { "X-GM-Password": "pw" },
    71→    });
    72→    expect(res.status).toBe(404);
    73→  });
    74→
    75→  it("GET /api/adventures/join/:playerLink returns 200 with limited info", async () => {
    76→    const adventure = createAdventure(ts.db, { name: "Join Test", gmPassword: "pw" });
    77→    const res = await fetch(`${ts.url}/api/adventures/join/${adventure.player_link}`);
    78→    expect(res.status).toBe(200);
    79→    const data = await res.json();
    80→    expect(data.id).toBe(adventure.id);
    81→    expect(data.name).toBe("Join Test");
    82→    expect(data.activeImageId).toBeNull();
    83→    expect(data.gm_password).toBeUndefined();
    84→  });
    85→
    86→  it("GET /api/adventures/join/:playerLink with unknown link returns 404", async () => {
    87→    const res = await fetch(`${ts.url}/api/adventures/join/unknownlink`);
    88→    expect(res.status).toBe(404);
    89→  });
    90→
    91→  it("PUT /api/adventures/:id/active-image updates adventure", async () => {
    92→    const adventure = createAdventure(ts.db, { name: "Test", gmPassword: "pw" });
    93→    const image = createImageRecord(ts.db, {
