      JSON.stringify({
        type: "fog:stroke",
        stroke: { x: 50, y: 50, radius: 20, mode: "reveal" },
      })
    );

    // Give the stroke time to be applied
    await new Promise((r) => setTimeout(r, 50));

    // Player joins late
    const player = track(
      await connectWS(ts.wsUrl, {
        adventureId,
        role: "player",
        playerLink,
        playerName: "Alice",
        playerColor: "#ff0000",
      })
    );
